def circularPickK(slices, k):
    NEG = -10 ** 18

    def line(a):
        prev2 = [0] + [NEG] * k
        prev1 = [0] + [NEG] * k
        for idx, x in enumerate(a):
            cur = prev1[:]
            for j in range(1, min(k, (idx + 2) // 2) + 1):
                v = prev2[j - 1] + x
                if v > cur[j]:
                    cur[j] = v
            prev2, prev1 = prev1, cur
        return prev1[k]

    return max(line(slices[:-1]), line(slices[1:]))
